import type { LessonSeed } from "../types";

export const part1: LessonSeed[] = [
  {
    w: 1, title: "Who Is the Holy Spirit?", theme: "The Holy Spirit is the third person of the Trinity, present everywhere and active from the beginning",
    summary: "Many Christians know the Father and the Son better than the Spirit. This opening lesson introduces the Holy Spirit as revealed in Scripture, from the opening verses of Genesis to the last chapter of Revelation, and shows why knowing him matters.",
    scripture: ["Genesis 1:1-2", "Psalm 139:7-10"], more: ["Job 33:4", "Acts 1:8", "Revelation 22:17"], memory: "Psalm 139:7",
    objectives: ["Explain who the Holy Spirit is according to Scripture", "Describe how the Spirit appears across the Bible", "Express a desire to know and depend on the Spirit"],
    terms: [["Holy Spirit", "The third person of the Trinity, equal with the Father and the Son."], ["Trinity", "One God in three persons: Father, Son and Holy Spirit."], ["Ruach", "The Hebrew word for spirit, breath or wind."]],
    intro: "Ask many believers to describe the Father and the Son, and they can say a good deal. Ask about the Holy Spirit, and some become uncertain. Some think of him as a force or an influence, some as a feeling, and some are afraid of the subject because of controversies. Yet the Bible gives the Spirit a central place. He hovered over the waters at creation, filled the prophets, descended on Jesus and was poured out on the church. This course will help us know him.",
    context: "In Genesis 1:2 the Spirit of God was hovering over the face of the waters. The Hebrew word ruach can mean breath, wind or spirit, and the Old Testament uses it for God's power and presence. In Psalm 139, David asks, 'Where shall I go from your Spirit? Or where shall I flee from your presence?' and concludes that there is nowhere he can escape from God. Jesus told his disciples that the Father would send them another Helper to be with them forever.",
    observe: "Psalm 139:7-10 declares that the Spirit is present in heaven, in Sheol, in the farthest parts of the sea, and that even there God's hand leads and holds. Job 33:4 says 'The Spirit of God has made me, and the breath of the Almighty gives me life.' In Acts 1:8, Jesus promises, 'You will receive power when the Holy Spirit has come upon you, and you will be my witnesses.' Revelation 22:17 closes the Bible with the Spirit and the Bride saying, 'Come.'",
    points: [
      ["The Spirit is active from creation to the new creation", "He hovered over the waters, gave life to humanity, empowered leaders and prophets, came upon Jesus, filled the church at Pentecost and will be with God's people forever. The Spirit is not a recent addition to God's work but has been present in all of it. His work always points to Christ and glorifies the Father."],
      ["The Spirit is everywhere present", "David found that no place was beyond the Spirit's reach. This is a comfort for the lonely, the afraid and the far from home, and a warning to those who think they can hide. Wherever believers go, the Spirit is with them. We cannot escape his presence, and for those in Christ we do not need to."],
      ["Knowing the Spirit changes how we live", "The Spirit gives new birth, assures us of our adoption, guides us into truth, produces fruit and gives gifts. Without him, Christianity becomes only a set of rules or a ritual. This course will explore who he is, what he does and how to depend on him daily. We begin with the simple request: Holy Spirit, teach us."],
    ],
    discuss: [
      ["What have you been taught or what do you think about the Holy Spirit? Where does your understanding come from?", "Let learners share honestly. Note areas of confusion or fear to address during the course."],
      ["Why do you think many Christians feel less certain about the Spirit than about the Father and Son?", "He is not seen, the subject is controversial and teaching has varied. Discuss patiently."],
      ["What does it mean to you that the Spirit is present everywhere?", "Comfort in loneliness, accountability in sin, assurance in danger. Invite personal reflection."],
      ["What do you hope to learn in this course?", "Record the questions on the board and return to them during the course."],
    ],
    apply: "Spend ten minutes each day this week reading a passage about the Spirit, such as John 14 to 16, and ask God to teach you. Write down any questions that arise. Pray daily, 'Holy Spirit, help me to know you and to follow you.'",
    activity: "On a large sheet, make a timeline from Genesis to Revelation. Ask learners to add places where the Spirit appears, such as creation, the prophets, the baptism of Jesus, Pentecost and the new creation. Read Genesis 1:2 and Acts 2:1-4 and talk about what is similar.",
    takeHome: "Read Genesis 1:1-2, Psalm 139, John 14:15-27 and Acts 2:1-4. List what each passage says about the Spirit. Write a prayer asking him to teach you.",
    prayer: "Thank God for the gift of his Spirit. Ask for a teachable heart. Pray that this course will deepen our relationship with the Holy Spirit.",
    teacher: "Learners come with a wide range of experiences and convictions about the Spirit, from deep experience to fear or confusion. Create a respectful atmosphere. Keep to Scripture and avoid claiming more certainty than the text gives on disputed matters. Remind learners that the Spirit always points to Christ.",
    assess: "Weekly check: ask learners to describe who the Holy Spirit is and where he appears in Scripture.",
    mcq1: ["What does Genesis 1:2 say the Spirit of God was doing?", ["Hovering over the face of the waters", "Resting in heaven", "Speaking to Adam", "Building the ark"], 0, "The Spirit was hovering over the waters at creation."],
    mcq2: ["What does Acts 1:8 promise when the Holy Spirit comes?", ["Power to be Christ's witnesses", "Great wealth", "An easy life", "A new law"], 0, "Jesus promised power and witness."],
    tf: ["The Holy Spirit first began to work at Pentecost.", false, "The Spirit was active in creation and throughout the Old Testament."],
    sa: ["Why is it important for Christians to know the Holy Spirit?", ["spirit", "god", "power", "life", "christ", "guide"], "A good answer says the Spirit is God, active in creation, salvation and the Christian life, and without him faith becomes rules or ritual."],
  },
  {
    w: 2, title: "The Spirit Is a Person, Not a Force", theme: "Scripture presents the Holy Spirit as a person who teaches, speaks, loves and can be grieved",
    summary: "Some think of the Spirit as an impersonal power. This lesson shows from John 14 to 16 and Ephesians 4 that the Holy Spirit has mind, will and emotion, and that we are called to relate to him personally.",
    scripture: ["John 14:15-17", "John 16:12-15"], more: ["Ephesians 4:30", "Acts 13:2", "Romans 8:26-27"], memory: "John 14:16-17",
    objectives: ["Show from Scripture that the Spirit is a person", "Describe the personal activities attributed to the Spirit", "Relate to the Spirit as a person, with respect and love"],
    terms: [["Helper", "A title for the Spirit meaning one who comes alongside to teach, comfort and assist."], ["Person", "One who has mind, will and the ability to relate."], ["Grieve", "To cause sorrow, as sin does to the Spirit."]],
    intro: "People sometimes speak of the Spirit as 'it', as if he were electricity or wind. The Bible never does that. Jesus uses personal pronouns for the Spirit. He promised another Helper, a word that points to a person like himself. The Spirit teaches, reminds, guides, speaks, intercedes, loves and can be grieved. If we treat the Spirit as a force to be used, we misunderstand him and miss relationship with him.",
    context: "On the night before his death, Jesus told his disciples that he would ask the Father and he would give them another Helper to be with them forever, the Spirit of truth. The word 'another' means another of the same kind, so the Spirit is like Jesus in being a person and being God. Jesus said the Spirit would teach them all things, bring to remembrance all that he had said and guide them into all the truth. Paul warned the Ephesians not to grieve the Holy Spirit of God.",
    observe: "John 16:13 says 'When the Spirit of truth comes, he will guide you into all the truth, for he will not speak on his own authority, but whatever he hears he will speak.' The pronoun 'he' is used even though the Greek word for spirit is neuter, showing that Jesus emphasises personhood. Acts 13:2 records the Holy Spirit saying, 'Set apart for me Barnabas and Saul for the work to which I have called them.' Romans 8:26 says the Spirit intercedes for us with groanings too deep for words.",
    points: [
      ["The Spirit has mind, will and emotion", "He knows the thoughts of God, according to 1 Corinthians 2. He decides how to distribute gifts, according to 1 Corinthians 12:11. He can be grieved, lied to and resisted. These are not the characteristics of a force but of a person. We respond to him as to someone we love and honour, not as to a tool we use."],
      ["The Spirit performs personal actions", "He teaches, reminds, speaks, guides, convicts, intercedes, testifies and calls people to ministry. He loves, as Paul writes of the love of the Spirit in Romans 15:30. In Acts 13 he spoke to the church in Antioch and directed them to send out Barnabas and Saul. Prayer and worship are meant to be relationship with him, not manipulation."],
      ["The Spirit points to Christ and glorifies him", "Jesus said that the Spirit would not speak about himself but would glorify Christ. The Spirit's ministry is to make Jesus known and loved. If a teaching or experience draws us away from Christ, it is not from the Spirit. A healthy relationship with the Spirit leads to greater love for the Father and the Son."],
    ],
    discuss: [
      ["Why do you think people tend to speak of the Spirit as a force?", "He is invisible and symbols like wind and fire are impersonal. Draw out why Scripture's personal language matters."],
      ["What difference does it make in prayer and worship if we treat the Spirit as a person?", "We seek relationship, listen and respond, rather than trying to use him. Share examples."],
      ["How can we grieve the Holy Spirit? What does that tell us about him?", "Through sin, bitterness and dishonesty. It shows that he is a person who cares."],
      ["How would you know whether an experience or teaching is truly from the Spirit?", "It exalts Christ, agrees with Scripture and produces godly fruit."],
    ],
    apply: "This week, practise speaking to the Spirit in prayer as you would to a close friend: thank him, ask him questions, and listen. Ask him to bring to mind anything that grieves him, and confess it. Check each experience or teaching you hear against Christ and Scripture.",
    activity: "Make two lists on the board: 'Things a force can do' and 'Things a person can do'. Read John 14:16-26, John 16:7-15 and Romans 8:26-27 and note each action of the Spirit. Ask learners which list the actions fit, and what that means for how we relate to him.",
    takeHome: "Read John 14 to 16, Acts 13:1-4 and Ephesians 4:25-32. List every personal action of the Spirit that you find. Write a prayer addressed directly to the Holy Spirit.",
    prayer: "Thank the Holy Spirit for being our Helper. Confess anything that grieves him. Ask him to lead us to Christ.",
    teacher: "Some groups, historically and today, deny that the Spirit is a person. Present the scriptural case calmly and gently. Be sensitive to learners from backgrounds where spirit is understood in other ways, such as ancestral or traditional spirits. Make clear the difference between the Holy Spirit and other spirits.",
    assess: "Weekly check: ask learners to give three examples from Scripture that show the Spirit is a person.",
    mcq1: ["What does Jesus call the Holy Spirit in John 14:16?", ["Another Helper", "A force", "A symbol", "An angel"], 0, "Jesus promised another Helper."],
    mcq2: ["What does Ephesians 4:30 tell us not to do?", ["Grieve the Holy Spirit of God", "Fear the Spirit", "Ignore the Spirit", "Test the Spirit"], 0, "Paul says do not grieve the Holy Spirit."],
    tf: ["The Bible describes the Holy Spirit as an impersonal power.", false, "It presents him as a person who speaks, teaches and can be grieved."],
    sa: ["Give two reasons that show the Holy Spirit is a person.", ["speaks", "teaches", "grieved", "guides", "mind", "will"], "A good answer names personal actions or traits, such as teaching, speaking, guiding, interceding, being grieved, or having mind and will."],
  },
  {
    w: 3, title: "The Spirit Is God", theme: "The Holy Spirit is fully divine, equal with the Father and the Son",
    summary: "The Spirit is not a lesser being. This lesson shows from Acts 5, 2 Corinthians 3 and Matthew 28 that Scripture calls the Spirit God, gives him divine attributes and places him in the same name with the Father and the Son.",
    scripture: ["Acts 5:1-4", "2 Corinthians 3:17-18"], more: ["Matthew 28:19", "Hebrews 9:14", "1 Corinthians 2:10-11"], memory: "2 Corinthians 3:17",
    objectives: ["Show from Scripture that the Holy Spirit is God", "Name divine attributes and works attributed to the Spirit", "Worship the Spirit together with the Father and the Son"],
    terms: [["Deity", "Being God in the fullest sense, with all the divine nature."], ["Omniscient", "Knowing all things, past, present and future."], ["Eternal", "Without beginning or end."]],
    intro: "The early church had to defend the truth that the Holy Spirit is God. Some argued that he was a created being or merely a power. The councils of Nicaea and Constantinople affirmed from Scripture that the Spirit is worshipped and glorified together with the Father and the Son. The proof does not rest on a single verse but on many passages that give the Spirit the names, attributes and works of God.",
    context: "In Acts 5, Ananias and Sapphira sold property and brought part of the proceeds to the apostles, pretending it was the whole. Peter said, 'Ananias, why has Satan filled your heart to lie to the Holy Spirit?... You have not lied to man but to God.' Lying to the Spirit is equated with lying to God. In the Great Commission Jesus tells the disciples to baptise in the name, singular, of the Father and of the Son and of the Holy Spirit.",
    observe: "In Acts 5:3-4 Peter moves from 'the Holy Spirit' to 'God' in one breath. Paul says in 2 Corinthians 3:17, 'Now the Lord is the Spirit', and speaks of the Lord who is the Spirit. Hebrews 9:14 says Christ offered himself through the eternal Spirit, ascribing eternity to him. 1 Corinthians 2:10-11 says the Spirit searches everything, even the depths of God, and no one comprehends the thoughts of God except the Spirit of God, showing omniscience.",
    points: [
      ["The Spirit is called God", "Peter says lying to the Holy Spirit is lying to God. Other passages use 'Spirit of God', 'Spirit of Christ' and 'Spirit of the Lord' interchangeably. The Spirit is not an agent of God distinct from God; he shares God's being. Scripture's equal treatment of the three persons in Matthew 28 and 2 Corinthians 13:14 supports this."],
      ["The Spirit has divine attributes", "He is eternal, present everywhere, all-knowing and all-powerful. He knows the deep things of God, fills creation, creates life and raises the dead. Romans 8:11 says the Spirit who raised Jesus from the dead will give life to our mortal bodies. These are things only God can do."],
      ["The Spirit shares the divine work and honour", "The Spirit is involved in creation, inspiration, regeneration, sanctification and resurrection. He is the one in whom believers have fellowship, and he is worshipped in the church. Christians pray to the Father, through the Son and in the Spirit. The Spirit is not a lesser partner but one of the three who are one God."],
    ],
    discuss: [
      ["Why was it important for the early church to affirm that the Spirit is fully God?", "Because worship and salvation depend on it. Draw out that a lesser being could not save or be worshipped."],
      ["What attributes of God do you see in the Spirit in the passages we read?", "Eternity, omniscience, omnipresence, power. Let learners find verses."],
      ["How should the deity of the Spirit affect our attitude toward him?", "Reverence, worship and obedience. Avoid treating him casually."],
      ["How would you explain the Trinity to a friend in simple words?", "One God in three persons, using Scripture. Avoid misleading analogies."],
    ],
    apply: "Include the Holy Spirit in your worship this week by praying or singing to him with reverence. Learn the Apostles' or Nicene Creed's statements about the Spirit. Be careful to speak truthfully, since lying to the Spirit is serious.",
    activity: "Make a three-column chart headed Father, Son and Holy Spirit. Fill in common names, attributes and works. Ask which items appear in all three columns. Read Matthew 28:19 and 2 Corinthians 13:14 and discuss why they list all three persons together.",
    takeHome: "Read Acts 5:1-11, 1 Corinthians 2:6-16, 2 Corinthians 13:14 and Hebrews 9:11-14. List the evidence that the Spirit is God. Write a short note explaining it to a friend.",
    prayer: "Worship the Holy Spirit together with the Father and the Son. Ask for reverence and honesty. Thank God for the unity of the Trinity.",
    teacher: "The doctrine of the Trinity is difficult, and learners may ask difficult questions. Be humble and point out that we affirm what Scripture says even where we cannot fully understand. Avoid analogies that suggest one God appearing in three roles or three separate gods. Be gentle with learners from other religious backgrounds.",
    assess: "Weekly check: ask learners to give two verses that show the Spirit is God.",
    mcq1: ["What did Peter say to Ananias in Acts 5:4?", ["You have not lied to man but to God", "You have lied to Peter", "You have lied to the church", "You have lied to the king"], 0, "Lying to the Holy Spirit was lying to God."],
    mcq2: ["In what name did Jesus tell the disciples to baptise in Matthew 28:19?", ["The Father, the Son and the Holy Spirit", "Moses", "The church", "The prophets"], 0, "He named all three persons together."],
    tf: ["The Bible teaches that the Holy Spirit is a created being.", false, "It teaches that the Spirit is eternal and fully God."],
    sa: ["How does Scripture show that the Holy Spirit is God?", ["god", "eternal", "lied", "names", "attributes", "worship"], "A good answer says Scripture calls him God, gives him divine attributes and works, and places him with the Father and Son in one name."],
  },
  {
    w: 4, title: "The Spirit in Creation and in the Old Testament", theme: "The Spirit gave life, empowered leaders and spoke through prophets before Christ came",
    summary: "The Holy Spirit was at work long before Pentecost. This lesson surveys his activity in creation, in the lives of leaders and craftsmen, and in the prophets who spoke God's word, and notes how the Old Testament looks forward to a greater outpouring.",
    scripture: ["Judges 6:34", "Isaiah 11:1-3"], more: ["Exodus 31:1-5", "Numbers 11:24-29", "Psalm 51:10-12"], memory: "Isaiah 11:2",
    objectives: ["Describe how the Spirit worked in the Old Testament", "Explain how the Old Testament anticipates a fuller coming of the Spirit", "Recognise that the God of the Old Testament is the same Spirit who works today"],
    terms: [["Anointing", "Being set apart and empowered by God for a task."], ["Prophet", "A person who speaks God's message by the Spirit."], ["Messiah", "The anointed one on whom the Spirit would rest fully."]],
    intro: "Some think the Holy Spirit only began to work at Pentecost. But the Spirit was active throughout the Old Testament. He hovered over creation, gave wisdom to Bezalel to build the tabernacle, came upon judges like Gideon and Samson to deliver Israel, inspired prophets to speak, and was prayed to by David after his sin. Understanding this helps us see the continuity of God's work and the greater promise that was coming.",
    context: "In Exodus 31, God said he had filled Bezalel with the Spirit of God, with ability and intelligence, with knowledge and all craftsmanship. In Judges 6:34, the Spirit of the Lord clothed Gideon, and he sounded the trumpet to rally Israel. In Numbers 11, the Spirit was put on seventy elders, and two men who had stayed in the camp also prophesied; Moses said, 'Would that all the Lord's people were prophets, that the Lord would put his Spirit on them!' Isaiah foresaw a shoot from the stump of Jesse on whom the Spirit would rest.",
    observe: "Isaiah 11:2 says 'And the Spirit of the Lord shall rest upon him, the Spirit of wisdom and understanding, the Spirit of counsel and might, the Spirit of knowledge and the fear of the Lord.' Psalm 51:11 has David praying, 'Cast me not away from your presence, and take not your Holy Spirit from me.' Old Testament experiences of the Spirit were often temporary and for particular tasks, and most people did not have the Spirit permanently within them. The prophets promised that this would change.",
    points: [
      ["The Spirit gave life, skill and leadership", "At creation he brought order and life. He gave craftsmen like Bezalel the skill to build the tabernacle, showing that the Spirit empowers practical work as well as preaching. He came upon leaders like Gideon and Samson for deliverance and on kings like David for rule. We should not separate the Spirit from ordinary vocations."],
      ["The Spirit inspired the prophets", "Peter says that no prophecy was ever produced by the will of man, but men spoke from God as they were carried along by the Holy Spirit. The Old Testament Scriptures came through his work. When we read them, we should expect the Spirit to illuminate them and point to Christ."],
      ["The Old Testament looks forward to a fuller outpouring", "Moses longed for all God's people to have the Spirit. Isaiah promised an anointed Messiah on whom the Spirit would rest. Joel promised that God would pour out his Spirit on all flesh. Ezekiel promised a new heart and God's Spirit within. These hopes were fulfilled in Jesus and at Pentecost."],
    ],
    discuss: [
      ["What surprises you about the work of the Spirit in the Old Testament?", "His involvement in craftsmanship, leadership and prophecy. Let learners share."],
      ["Why do you think the Spirit came on people temporarily in the Old Testament?", "God was preparing his people for the new covenant, when the Spirit would dwell permanently in all believers."],
      ["What does the example of Bezalel tell us about the Spirit and everyday skills?", "God gifts people for all kinds of work. Discuss how to honour God in our trades."],
      ["Why did David pray 'Take not your Holy Spirit from me'?", "He feared losing God's presence after his sin. Compare with the new covenant promise."],
    ],
    apply: "Thank God for any practical skill he has given you and ask how to use it for his glory. Read one prophetic passage this week, asking the Spirit to open it to you. Pray Psalm 51:10-12 as your own prayer for a clean heart and the joy of salvation.",
    activity: "Prepare cards listing Old Testament figures and tasks: Bezalel, Gideon, Samson, David, Isaiah and the seventy elders. Ask learners to match each with the Spirit's work: craftsmanship, deliverance, strength, kingship, prophecy and shared leadership. Read the key passages and discuss.",
    takeHome: "Read Exodus 31:1-11, Judges 6:33-35, Numbers 11:24-30 and Isaiah 11:1-9. List ways the Spirit worked. Write a prayer thanking God for the Spirit's work in Scripture.",
    prayer: "Thank God for the Spirit who inspired Scripture. Ask for his help in daily work. Pray for revival like the prophets longed for.",
    teacher: "Learners may be surprised that the Spirit worked before Pentecost. Explain that Pentecost was a new stage, not the first appearance. Avoid dividing history too sharply, and avoid overstating differences between the testaments. Keep returning to the promise and fulfilment pattern.",
    assess: "Weekly check: ask learners to name two ways the Spirit worked in the Old Testament.",
    mcq1: ["Whom did God fill with the Spirit to build the tabernacle in Exodus 31?", ["Bezalel", "Moses", "Aaron", "Joshua"], 0, "God filled Bezalel with the Spirit of God for craftsmanship."],
    mcq2: ["What did Moses wish in Numbers 11:29?", ["That all the Lord's people were prophets and had his Spirit", "That no one had the Spirit", "That only kings had the Spirit", "That the Spirit would leave"], 0, "He wished that the Lord would put his Spirit on all."],
    tf: ["The Holy Spirit did not exist or act before Pentecost.", false, "He was active from creation throughout the Old Testament."],
    sa: ["Name two ways the Holy Spirit worked in the Old Testament and one promise about the future.", ["creation", "craftsmen", "judges", "prophets", "outpouring", "messiah"], "A good answer names examples such as creation, craftsmanship, judges or prophecy, and a promise such as the outpouring on all God's people or the anointed Messiah."],
  },
  {
    w: 5, title: "The Spirit and Jesus", theme: "Jesus was conceived by the Spirit, anointed by the Spirit and lived and ministered in the Spirit's power",
    summary: "The relationship between Jesus and the Spirit is close and constant. This lesson follows the Spirit through the life of Christ, from conception to baptism to temptation to ministry to resurrection, and shows how Jesus is our model for life in the Spirit.",
    scripture: ["Luke 4:14-19", "Acts 10:37-38"], more: ["Luke 1:35", "Matthew 3:16", "Romans 1:3-4"], memory: "Acts 10:38",
    objectives: ["Trace the work of the Spirit in the life of Jesus", "Explain what it means that Jesus was anointed by the Spirit", "Follow Jesus' example of depending on the Spirit"],
    terms: [["Anointed", "Set apart and empowered by the Spirit."], ["Conceived by the Holy Spirit", "The way Jesus was born of Mary without a human father."], ["Christ", "The Greek word for the Anointed One."]],
    intro: "The word Christ means the anointed one, and the anointing is by the Holy Spirit. Jesus did not perform his ministry by independent divine power alone but in dependence on the Spirit, as the true man. The Gospels show the Spirit at every step: at the conception, the baptism, the temptation, the Nazareth sermon, the miracles and the resurrection. If the Son of God lived in the Spirit's power, how much more must we?",
    context: "The angel told Mary that the Holy Spirit would come upon her, and the power of the Most High would overshadow her. At the Jordan the Spirit descended on Jesus like a dove. Immediately he was led by the Spirit into the wilderness. Returning in the power of the Spirit to Galilee, he read from Isaiah 61, 'The Spirit of the Lord is upon me, because he has anointed me.' Peter told Cornelius how God anointed Jesus of Nazareth with the Holy Spirit and with power, and he went about doing good and healing all who were oppressed by the devil.",
    observe: "Luke emphasises the Spirit repeatedly: 'full of the Holy Spirit' (4:1), 'led by the Spirit' (4:1), 'in the power of the Spirit' (4:14), 'the Spirit of the Lord is upon me' (4:18) and 'rejoiced in the Holy Spirit' (10:21). Romans 1:4 says Jesus was declared to be the Son of God in power according to the Spirit of holiness by his resurrection from the dead. Hebrews 9:14 says he offered himself without blemish to God through the eternal Spirit.",
    points: [
      ["The Spirit was present at every stage of Jesus' life", "He was conceived by the Spirit, anointed at his baptism, led into temptation and empowered for ministry. His miracles were done in the power of the Spirit, and his offering on the cross was through the eternal Spirit. The Spirit raised him from the dead. This does not reduce Christ's divinity but shows his true humanity and the unity of the Trinity in salvation."],
      ["Jesus' ministry was Spirit-empowered", "In Nazareth he announced that the Spirit had anointed him to preach good news, proclaim liberty and heal. When critics accused him of casting out demons by Beelzebul, he said, 'if it is by the Spirit of God that I cast out demons, then the kingdom of God has come upon you.' The kingdom comes by the Spirit's power."],
      ["Jesus is our model for dependence on the Spirit", "Though he was God, Jesus prayed, fasted and relied on the Spirit as a man. Believers are called to walk in the same Spirit. After his resurrection, Jesus poured out the Spirit on the church so that we may share his anointing and his mission. The same Spirit who anointed Jesus now anoints his people."],
    ],
    discuss: [
      ["How does it change your view of Jesus to see that he lived in the Spirit's power?", "It shows his true humanity and gives us a pattern. Draw out his dependence on the Father and the Spirit."],
      ["What does Luke 4:18-19 tell us about the purpose of the Spirit's anointing?", "To bring good news, release and healing to others. The Spirit empowers service."],
      ["Why is it important that the Spirit is involved in Jesus' sacrifice and resurrection?", "The whole Trinity works together in salvation. Hebrews 9:14 and Romans 1:4."],
      ["How can we depend on the Spirit in daily ministry as Jesus did?", "Prayer, Scripture, obedience, listening and fasting. Discuss practical habits."],
    ],
    apply: "Before key decisions or tasks this week, pause and pray, asking the Spirit to lead and empower you as he did Jesus. Read Luke 4 and 5 and note the connection between prayer, the Spirit and ministry. Look for one chance to bring good news or help to someone in need.",
    activity: "Make a timeline of the life of Jesus on the board and ask learners to mark where the Spirit is mentioned: conception, baptism, temptation, Nazareth, ministry, cross and resurrection. Read the verses together and discuss what each shows. Close with prayer for the Spirit's help in ministry.",
    takeHome: "Read Luke 1:26-35, Luke 3:21-22, Luke 4:1-21, Acts 10:34-43 and Hebrews 9:11-14. Write a paragraph on the Spirit's role in the life of Jesus. Pray for the Spirit's power in your daily tasks.",
    prayer: "Thank Jesus for living in dependence on the Spirit. Ask for the same Spirit to empower us. Pray for those who serve the poor and sick.",
    teacher: "Be careful not to suggest that Jesus was not divine because he relied on the Spirit. The Gospels present him as truly God and truly man. Keep the focus on his example and the unity of the Trinity. Learners may ask technical questions; admit mystery where it exists.",
    assess: "Weekly check: ask learners to name three events in Jesus' life where the Spirit is mentioned.",
    mcq1: ["What did Jesus read in the synagogue at Nazareth in Luke 4:18?", ["The Spirit of the Lord is upon me, because he has anointed me", "The Lord is my shepherd", "In the beginning was the Word", "Blessed are the poor"], 0, "He read from Isaiah 61."],
    mcq2: ["How does Acts 10:38 describe Jesus?", ["Anointed with the Holy Spirit and with power", "A scribe of the law", "A leader of an army", "A priest of the temple"], 0, "God anointed him with the Holy Spirit and power."],
    tf: ["Jesus' ministry was unconnected to the Holy Spirit.", false, "The Gospels show the Spirit at every stage."],
    sa: ["How was the Holy Spirit involved in the life of Jesus?", ["conceived", "baptism", "led", "power", "anointed", "ministry"], "A good answer names several stages such as conception, baptism, temptation, ministry and resurrection, showing the Spirit's presence and power."],
  },
  {
    w: 6, title: "The Promise of the Spirit", theme: "Prophets and Jesus promised a greater outpouring of the Spirit for all God's people",
    summary: "The Old Testament prophets looked forward to a day when God would pour out his Spirit on all his people, and Jesus repeated and expanded the promise. This lesson studies Joel, Ezekiel and the Upper Room discourse to understand what was promised and why.",
    scripture: ["Joel 2:28-29", "John 14:16-26"], more: ["Ezekiel 36:26-27", "Acts 1:4-8", "Luke 24:49"], memory: "Joel 2:28",
    objectives: ["Describe the Old Testament promises of the Spirit", "Explain what Jesus promised in the Upper Room", "Wait on God and expect his Spirit to work"],
    terms: [["Pour out", "To give abundantly, like water poured on dry ground."], ["Helper", "The Spirit as one who comes alongside to teach and comfort."], ["New covenant", "God's promise of forgiveness, a new heart and the Spirit in his people."]],
    intro: "God does not leave his people without promises. In the Old Testament, the Spirit rested on a few; the prophets said that one day he would be given to all. Joel foretold that sons and daughters would prophesy, old men would dream and young men would see visions, even on servants. Ezekiel promised a heart of flesh and God's own Spirit within. Jesus told his disciples that this promise was about to be fulfilled.",
    context: "Joel prophesied after a plague of locusts and called Judah to repentance. He promised that after the judgment, God would restore and pour out his Spirit on all flesh. Ezekiel, among the exiles in Babylon, promised a new heart and a new Spirit. In the Upper Room Jesus told his troubled disciples that he would not leave them as orphans, that the Spirit would be with them and in them, and that it was to their advantage that he go away so that the Helper would come.",
    observe: "Joel 2:28-29: 'And it shall come to pass afterward, that I will pour out my Spirit on all flesh; your sons and your daughters shall prophesy, your old men shall dream dreams, and your young men shall see visions. Even on the male and female servants in those days I will pour out my Spirit.' In John 14:17 Jesus says of the Spirit of truth: 'You know him, for he dwells with you and will be in you.' Acts 1:4 records that Jesus told them not to depart from Jerusalem, but to wait for the promise of the Father.",
    points: [
      ["The promise was for all God's people", "Joel makes no distinction of gender, age or class. The Spirit would be poured out on sons and daughters, old and young, free and slave. This was a radical widening of the Old Testament pattern. Peter later says this promise is for you and for your children and for all who are far off, everyone whom the Lord our God calls to himself."],
      ["The Spirit would change hearts and dwell within", "Ezekiel's promise is that God would give a new heart and put his Spirit within his people to cause them to walk in his statutes. This is the inner transformation that the law could not produce. In John 14, Jesus said the Spirit who had been with them would be in them. He would make Jesus present in a new way."],
      ["Waiting for the promise requires trust and prayer", "Jesus told the disciples to wait in Jerusalem. They obeyed and continued in prayer. Waiting was not passive but expectant and united. Believers today do not wait for the Spirit to come for the first time but depend on him continually, praying to be filled and to walk in his power."],
    ],
    discuss: [
      ["How would the promise of Joel have sounded to people who had been excluded because of age, gender or status?", "As wonderful news. Discuss how the church today should reflect this inclusivity."],
      ["What does Jesus mean when he says it is to your advantage that he goes away?", "Because the Spirit would be with all believers everywhere and in a deeper way. Discuss the comfort of the Spirit."],
      ["Why do you think the disciples had to wait before they received the Spirit?", "The timing was part of God's plan, and waiting prepared them. Discuss patience and obedience."],
      ["What promises of God are you waiting for, and how are you waiting?", "Invite personal sharing and encourage prayer, patience and trust."],
    ],
    apply: "Write out Joel 2:28-29 and pray it for your church, your family and your community. Ask God to pour out his Spirit and to give you a new sensitivity to his leading. Pray with someone else daily this week.",
    activity: "Divide into three groups to study Joel 2:28-32, Ezekiel 36:24-28 and John 14:15-26. Each group lists what the passage promises, to whom and with what purpose. Compare the lists on the board and ask how the promises fit together.",
    takeHome: "Read Joel 2, Ezekiel 36, John 14 to 16 and Acts 1:1-14. Write a one-page summary of the promises of the Spirit. Pray each day for a fresh work of the Spirit in your life.",
    prayer: "Thank God for the promise of the Spirit. Ask him to pour out his Spirit on our church and community. Pray in expectation and unity.",
    teacher: "Traditions differ on how the promises of Joel apply today. Present what the passages say and how Peter applies them, without insisting on particular patterns of experience. Encourage learners to pray and expect God to work. Be sensitive to those who feel they have not experienced much of the Spirit.",
    assess: "Weekly check: ask learners to give one Old Testament promise and one promise of Jesus about the Spirit.",
    mcq1: ["Upon whom did Joel say God would pour out his Spirit?", ["All flesh: sons, daughters, old, young and servants", "Only priests", "Only kings", "Only prophets"], 0, "He said all flesh, including servants."],
    mcq2: ["What did Jesus tell the disciples to do in Acts 1:4?", ["Wait for the promise of the Father", "Return to Galilee", "Start preaching at once", "Build a temple"], 0, "He told them to wait for the promise."],
    tf: ["Jesus promised that the Spirit would be with and in his disciples.", true, "John 14:17 says he dwells with you and will be in you."],
    sa: ["What did the prophets and Jesus promise about the Holy Spirit?", ["pour out", "all", "heart", "dwell", "helper", "power"], "A good answer says God would pour out his Spirit on all his people, give a new heart and dwell in them, and Jesus promised the Helper to be with and in them."],
  },
  {
    w: 7, title: "Pentecost: The Spirit Poured Out", theme: "On the day of Pentecost the Spirit came on the waiting disciples and the church was born",
    summary: "Acts 2 records the arrival of the Spirit in power. This lesson narrates the events of Pentecost, explains the signs of wind, fire and languages, studies Peter's sermon and shows how the day marks the start of the church's mission.",
    scripture: ["Acts 2:1-21", "Acts 2:37-47"], more: ["Joel 2:28-32", "Genesis 11:1-9", "John 7:37-39"], memory: "Acts 2:4",
    objectives: ["Narrate the events of Pentecost from Acts 2", "Explain the meaning of the signs and Peter's use of Joel", "See Pentecost as the birth of the church and its mission"],
    terms: [["Pentecost", "A Jewish feast fifty days after Passover, when the Spirit was poured out."], ["Tongues", "Languages, here speech in the languages of the visitors."], ["Church", "The people of God gathered by the Spirit around Christ."]],
    intro: "Ten days after Jesus ascended, about a hundred and twenty believers were together in Jerusalem, praying. Suddenly there came from heaven a sound like a mighty rushing wind, and divided tongues as of fire rested on each of them. They were filled with the Holy Spirit and began to speak in other languages. A crowd gathered, amazed. Peter stood up and explained: this is what was spoken by the prophet Joel. The church was born.",
    context: "Pentecost was one of the three major Jewish feasts, bringing pilgrims from many nations to Jerusalem. Acts 2 lists the regions they came from. The believers had been waiting, as Jesus told them. When the Spirit came, they declared the mighty works of God in the languages of the visitors. Some mocked, saying they were drunk. Peter replied that it was only nine in the morning and quoted Joel. He then preached Christ, crucified and risen, and about three thousand were baptised that day.",
    observe: "Acts 2:4 says they were all filled with the Holy Spirit and began to speak in other tongues as the Spirit gave them utterance. The wind and fire recall God's appearances at Sinai. The languages reverse the judgment at Babel, where languages were confused. Peter's sermon moves from Joel to David to Jesus, ending with the call, 'Repent and be baptized every one of you in the name of Jesus Christ for the forgiveness of your sins, and you will receive the gift of the Holy Spirit.' Verses 42 to 47 describe the life of the new community.",
    points: [
      ["The Spirit came as promised and in power", "Jesus had promised power, Joel had promised outpouring, and now it happened. The signs of wind and fire showed the presence of God. The believers were filled and empowered to witness. Pentecost does not repeat as the original event but its effects continue as the Spirit fills and empowers God's people."],
      ["The Spirit overcomes barriers and brings the gospel to the nations", "At Babel, languages were scattered in judgment; at Pentecost, people from many nations heard the good news in their own languages. The Spirit enables the gospel to cross cultural and linguistic lines. This foreshadows the global church, and challenges us to speak the gospel in ways people understand."],
      ["The Spirit creates a new community", "Those who received the word were baptised and devoted themselves to the apostles' teaching, fellowship, the breaking of bread and prayer. They shared possessions, worshipped together and grew daily. A Spirit-filled church is marked by teaching, love, generosity, worship and mission. The result was that the Lord added to their number day by day."],
    ],
    discuss: [
      ["Why do you think God used wind, fire and languages as signs at Pentecost?", "They recall earlier appearances of God and the reversal of Babel, and signalled the Spirit's presence and the gospel for all."],
      ["How does Peter use Scripture to explain what is happening?", "He quotes Joel and David and shows how they point to Jesus. Discuss the importance of the Bible in explaining experience."],
      ["What marked the life of the early church after Pentecost?", "Teaching, fellowship, bread and prayer, generosity and joy. Discuss how your church can grow in these."],
      ["How can your church speak the gospel in ways that people from different backgrounds can understand?", "Language, culture, simple words. Discuss practical steps your church could take."],
    ],
    apply: "Read Acts 2:42-47 and choose one of the habits of the early church to strengthen this week: teaching, fellowship, meals, prayer or generosity. Pray for people of other languages or cultures in your area and consider how to share the gospel with them.",
    activity: "Retell Pentecost through a drama with a narrator, believers, the crowd and Peter. After the performance, ask learners to describe each part of the story: the prayer, the sound, the fire, the languages, the crowd and the sermon. List the results of the day and discuss how to see similar fruit today.",
    takeHome: "Read Acts 2 in full and Genesis 11:1-9. Write a paragraph on how Pentecost reverses Babel. Pray for the spread of the gospel to a people who have not heard.",
    prayer: "Thank God for sending the Spirit. Pray for the church to be filled and unified. Ask for opportunities to share the gospel across barriers.",
    teacher: "Traditions have different views on whether Pentecost is repeatable and on the nature of the tongues spoken. Present the text and avoid pressing a single view. Focus on the Spirit's power, the witness to Christ and the formation of the community. Welcome sincere questions.",
    assess: "Weekly check: ask learners what happened at Pentecost and how the crowd responded.",
    mcq1: ["What happened to the believers in Acts 2:4?", ["They were filled with the Holy Spirit and spoke in other tongues", "They were scattered", "They were arrested", "They fell asleep"], 0, "They were filled with the Spirit and spoke in other languages."],
    mcq2: ["How many people were added to the church that day according to Acts 2:41?", ["About three thousand", "About twelve", "About one hundred and twenty", "About five hundred"], 0, "About three thousand were baptised."],
    tf: ["Peter explained the events of Pentecost by quoting the prophet Joel.", true, "He said this is what was spoken by the prophet Joel."],
    sa: ["What did the Spirit's coming at Pentecost accomplish?", ["power", "witness", "nations", "church", "languages", "gospel"], "A good answer says the Spirit empowered the disciples to witness, the gospel was heard across languages, many believed and the church was formed."],
  },
  {
    w: 8, title: "The Spirit and Scripture: Inspired and Illumined", theme: "The Holy Spirit gave us the Bible and helps us understand it",
    summary: "The Bible is the product of the Spirit's work in inspiring its authors, and the Spirit still illuminates readers. This lesson studies 2 Timothy 3 and 2 Peter 1 on inspiration, and John 16 and 1 Corinthians 2 on illumination.",
    scripture: ["2 Timothy 3:14-17", "2 Peter 1:19-21"], more: ["1 Corinthians 2:12-14", "John 16:12-15", "Psalm 119:18"], memory: "2 Timothy 3:16",
    objectives: ["Explain how the Spirit inspired the Scriptures", "Describe how the Spirit helps believers understand the Bible", "Read Scripture with prayerful dependence on the Spirit"],
    terms: [["Inspiration", "The Spirit's work in causing the biblical authors to write what God intended."], ["Illumination", "The Spirit's work in helping readers understand and apply Scripture."], ["God-breathed", "The meaning of the Greek word translated 'inspired by God'."]],
    intro: "We hold the Bible in our hands, but how did it come to us, and how can we understand it? Paul says all Scripture is breathed out by God. Peter says men spoke from God as they were carried along by the Holy Spirit. Jesus promised that the Spirit would guide the apostles into all truth. Yet we also need the Spirit's help to understand, for the natural person does not accept the things of the Spirit of God. This lesson holds both truths.",
    context: "Paul writes to Timothy, urging him to continue in what he has learned from childhood, the sacred writings that are able to make him wise for salvation through faith in Christ Jesus. Peter assures the readers that the prophetic word is more fully confirmed and urges them to pay attention to it as to a lamp shining in a dark place. Paul tells the Corinthians that we have received the Spirit who is from God, that we might understand the things freely given us by God.",
    observe: "2 Timothy 3:16-17: 'All Scripture is breathed out by God and profitable for teaching, for reproof, for correction, and for training in righteousness, that the man of God may be complete, equipped for every good work.' 2 Peter 1:21: 'For no prophecy was ever produced by the will of man, but men spoke from God as they were carried along by the Holy Spirit.' In John 16:13 Jesus said that the Spirit of truth would guide the apostles into all the truth. In 1 Corinthians 2:14 Paul says the natural person does not accept the things of the Spirit of God.",
    points: [
      ["The Spirit inspired the Scriptures", "God breathed out his word through human authors with their own personalities, styles and circumstances. The Spirit carried them along so that what they wrote was what God wanted written. This is why the Bible is trustworthy and authoritative. Christians differ on the details of how to describe inspiration, but all agree that Scripture is God's word."],
      ["The Spirit illuminates the Scriptures for readers", "We do not need new revelation, but we do need the Spirit's help to understand and apply the Bible. Paul says the Spirit enables us to understand what God has freely given. The psalmist prayed, 'Open my eyes, that I may behold wondrous things out of your law.' We should read the Bible prayerfully, asking the Spirit for understanding."],
      ["The Spirit works with the word, not apart from it", "The Spirit never contradicts what he inspired. Experiences, impressions and teachings must be tested against Scripture. The early Bereans were commended for examining the Scriptures daily to see if what Paul said was true. A healthy Christian life holds word and Spirit together: the Spirit uses the word, and the word is understood by the Spirit."],
    ],
    discuss: [
      ["Why is it important that the Bible has both a divine and a human author?", "It shows God's word comes in human language, with trustworthy meaning. Discuss how both are honoured."],
      ["What helps you to understand the Bible when you read it?", "Prayer, context, teaching, fellowship. Share personal tips that have helped."],
      ["How should believers respond when someone claims a new revelation that contradicts Scripture?", "Test it by Scripture and reject what contradicts. See Acts 17:11 and Galatians 1:8."],
      ["What attitude should we bring to reading and hearing the word?", "Humility, expectation, readiness to obey. Discuss James 1:21-25."],
    ],
    apply: "Begin each Bible reading this week with a short prayer, asking the Spirit to open your eyes and help you obey. Write down one thing you learn each day and one way to apply it. Check any teaching you hear against Scripture, like the Bereans.",
    activity: "Pair learners to read 2 Timothy 3:14-17 and 2 Peter 1:19-21. Each pair lists what these passages say about the origin, purpose and use of Scripture. Share findings, then spend a few minutes reading a short passage together and asking the Spirit's help to understand it.",
    takeHome: "Read 2 Timothy 3, 2 Peter 1:16-21, 1 Corinthians 2:6-16 and Psalm 119:1-24. Write a short prayer for illumination to use before Bible reading. Commit to a daily reading plan.",
    prayer: "Thank God for the gift of Scripture. Ask the Spirit to open our eyes and hearts to understand and obey. Pray for those who translate and teach the Bible.",
    teacher: "Learners may have different views about the nature of inspiration and the interpretation of Scripture. Hold to the church's historic confession that the Bible is God's word, and avoid unnecessary disputes. Be ready to help learners with low literacy; use listening, memory and group reading.",
    assess: "Weekly check: ask learners to distinguish inspiration from illumination.",
    mcq1: ["What does 2 Timothy 3:16 say about Scripture?", ["All Scripture is breathed out by God", "Some Scripture is from God", "Scripture is human opinion", "Scripture is a mystery"], 0, "Paul says all Scripture is God-breathed."],
    mcq2: ["How did the prophets speak, according to 2 Peter 1:21?", ["As they were carried along by the Holy Spirit", "By their own will", "By tradition", "By chance"], 0, "They spoke from God as carried along by the Spirit."],
    tf: ["The Spirit helps believers understand Scripture.", true, "1 Corinthians 2 and John 16 teach that the Spirit illuminates the word."],
    sa: ["What is the difference between inspiration and illumination?", ["inspiration", "illumination", "author", "reader", "spirit", "understand"], "A good answer says inspiration is the Spirit's work in producing Scripture through its authors, and illumination is his work in helping readers understand and apply it."],
  },
  {
    w: 9, title: "The Spirit Convicts the World", theme: "The Holy Spirit shows people their sin, the righteousness of Christ and the certainty of judgment",
    summary: "No one comes to Christ without the Spirit's work. This lesson studies John 16:7-11 and Acts 2:37 to understand how the Spirit convicts of sin, righteousness and judgment, and how we can cooperate with that work in witness and in our own lives.",
    scripture: ["John 16:7-11", "Acts 2:36-41"], more: ["Acts 24:25", "Romans 2:4", "2 Corinthians 7:8-10"], memory: "John 16:8",
    objectives: ["Explain what the Spirit convicts the world of and why", "Distinguish conviction from condemnation", "Rely on the Spirit when sharing the gospel"],
    terms: [["Conviction", "The Spirit's work of making a person aware of sin and need."], ["Righteousness", "Right standing with God, found in Christ."], ["Judgment", "God's verdict, including the defeat of the ruler of this world."]],
    intro: "No amount of clever argument can make a person feel the weight of sin. Guilt may be stirred by fear or shame, but true conviction, leading to repentance and faith, is the Spirit's work. Jesus told his disciples that when the Helper comes, he will convict the world concerning sin and righteousness and judgment. This is wonderful news for evangelism: we are not left to persuade people in our own strength.",
    context: "Jesus spoke these words to his disciples in the Upper Room, preparing them for his departure. He explained that the Spirit would convict the world about sin because they do not believe in him, about righteousness because he was going to the Father, where they would see him no longer, and about judgment because the ruler of this world is judged. At Pentecost Peter's sermon pierced the hearts of listeners, and they asked, 'Brothers, what shall we do?'",
    observe: "John 16:9-11 gives three areas of conviction. The central sin the Spirit exposes is unbelief in Jesus. The righteousness is that of Christ, vindicated by his going to the Father, and offered to sinners. The judgment is that of Satan, who has been defeated at the cross. Acts 2:37 says that when the people heard Peter's sermon they were cut to the heart. Romans 2:4 says God's kindness is meant to lead you to repentance.",
    points: [
      ["The Spirit convicts of sin, especially unbelief", "He shows people that they have fallen short of God's glory and that the root of sin is refusing to trust Christ. This is more than feeling bad about particular acts. It is a recognition of our need and of rebellion against God. Without conviction, the gospel seems unnecessary."],
      ["The Spirit convicts of righteousness and judgment", "He shows that Jesus is the righteous one, vindicated by the resurrection and ascension, and that righteousness is available through him. He also shows that judgment is real, but the ruler of this world has been condemned at the cross, so those who trust Christ need not fear. The Spirit points both to the seriousness of sin and to the sufficiency of Christ."],
      ["Conviction leads to repentance, not despair", "Paul distinguishes godly grief that produces repentance from worldly grief that produces death. Conviction by the Spirit is specific and points to Christ. Condemnation by the accuser is vague, harsh and without hope. When we feel conviction, we should confess and receive forgiveness. In evangelism, we should pray for the Spirit to work, and speak the truth in love."],
    ],
    discuss: [
      ["How have you experienced the Spirit's conviction in your life?", "Invite testimonies of conviction leading to repentance. Handle confidences carefully."],
      ["What is the difference between conviction and condemnation?", "Conviction is specific, leads to repentance and points to forgiveness. Condemnation accuses and leaves us hopeless."],
      ["How does knowing that the Spirit convicts help you in sharing the gospel?", "We do not need to force or manipulate. We trust the Spirit to work. We still speak clearly."],
      ["Why do you think the Spirit's chief concern is unbelief in Jesus?", "Because Christ is the answer to sin and the way of righteousness."],
    ],
    apply: "Pray for three people by name this week, asking the Spirit to convict and draw them to Christ. Share the gospel with at least one, trusting the Spirit. Ask the Spirit to show you any sin you need to confess and respond quickly with repentance and faith.",
    activity: "Draw a scale with 'Worldly sorrow' on one side and 'Godly sorrow' on the other. Ask learners to list how each looks and what results, using 2 Corinthians 7:10. Read Acts 2:36-41 and discuss how Peter's hearers responded and what the Spirit did in them.",
    takeHome: "Read John 16:5-15, Acts 2:36-41, Acts 24:24-27 and 2 Corinthians 7:8-13. Write a paragraph on how the Spirit convicts. Pray for someone you want to see come to faith.",
    prayer: "Thank the Spirit for convicting us. Ask him to show us our sin and Christ's righteousness. Pray for those who do not yet believe.",
    teacher: "Some learners have been hurt by harsh preaching that used guilt as a weapon. Distinguish carefully between the Spirit's gracious conviction and human manipulation. Do not demand emotional reactions. Be ready to pray with anyone who feels convicted, and to refer them to pastoral help.",
    assess: "Weekly check: ask learners to name the three things the Spirit convicts the world of in John 16:8.",
    mcq1: ["Of what three things does the Spirit convict the world in John 16:8?", ["Sin, righteousness and judgment", "Love, joy and peace", "Wealth, power and fame", "Faith, hope and love"], 0, "Jesus said sin, righteousness and judgment."],
    mcq2: ["What did the crowd ask Peter after his sermon in Acts 2:37?", ["Brothers, what shall we do?", "Who are you?", "Where is Jesus?", "Why are you speaking?"], 0, "They were cut to the heart and asked what to do."],
    tf: ["Conviction by the Spirit leaves a person hopeless.", false, "Conviction leads to repentance and forgiveness in Christ."],
    sa: ["How does the Spirit convict people and what should they do?", ["sin", "righteousness", "judgment", "repent", "believe", "christ"], "A good answer says the Spirit shows people their sin, Christ's righteousness and the reality of judgment, leading them to repent and believe."],
  },
  {
    w: 10, title: "Born of the Spirit", theme: "New birth is the Spirit's work, giving spiritual life to those who were dead in sin",
    summary: "Jesus told Nicodemus that unless one is born again he cannot see the kingdom of God. This lesson studies John 3 and Titus 3 to explain regeneration as the work of the Spirit, its necessity and its marks.",
    scripture: ["John 3:1-8", "Titus 3:4-7"], more: ["Ezekiel 36:25-27", "Ephesians 2:1-5", "1 Peter 1:3"], memory: "John 3:5-6",
    objectives: ["Explain what it means to be born of the Spirit", "Describe why new birth is necessary", "Trust in the Spirit's work and share the call to new birth"],
    terms: [["Regeneration", "The Spirit's work of giving new spiritual life."], ["Born again", "Receiving new life from above through the Spirit."], ["Washing of rebirth", "Titus 3:5, the cleansing and renewal by the Holy Spirit."]],
    intro: "Nicodemus was a respected teacher of Israel, a Pharisee and member of the Jewish council. He came to Jesus by night and began with a compliment. Jesus replied abruptly: 'Truly, truly, I say to you, unless one is born again he cannot see the kingdom of God.' Nicodemus was confused. How can a man be born when he is old? Jesus explained that new birth is a work of the Spirit, which is as mysterious and powerful as the wind.",
    context: "Jews believed they belonged to God's kingdom by descent from Abraham and by keeping the law. Jesus said that was not enough. Ezekiel 36 had promised that God would sprinkle clean water on his people, give them a new heart and put his Spirit within them. This is what Jesus meant by being born of water and the Spirit. Titus 3 says God saved us, not because of works done by us in righteousness, but according to his own mercy, by the washing of regeneration and renewal of the Holy Spirit.",
    observe: "In John 3:5-6 Jesus says 'Truly, truly, I say to you, unless one is born of water and the Spirit, he cannot enter the kingdom of God. That which is born of the flesh is flesh, and that which is born of the Spirit is spirit.' Verse 8: 'The wind blows where it wishes, and you hear its sound, but you do not know where it comes from or where it goes. So it is with everyone who is born of the Spirit.' Ephesians 2:1 describes people as dead in trespasses and sins before God made them alive.",
    points: [
      ["New birth is necessary because we are spiritually dead", "Flesh gives birth to flesh. Human effort, religion or heritage cannot produce spiritual life. Paul describes unbelievers as dead in trespasses, unable to respond to God. Without regeneration, no one can see or enter the kingdom. This is humbling but also frees us from trying to earn life."],
      ["New birth is the Spirit's sovereign work", "Like wind, the Spirit blows where he wishes. We cannot control or predict his work, but we see its effects. God makes us alive by his mercy, as Titus 3 says, through the washing of regeneration and renewal of the Holy Spirit. We do not give birth to ourselves any more than a baby does. Faith itself is a gift."],
      ["New birth produces a changed life", "Those who are born of the Spirit begin to love God, hate sin, believe in Christ and love other believers. 1 John describes marks of the born-again: they do not make a practice of sinning, they do righteousness, they love one another and they believe that Jesus is the Christ. Changes are seen over time. The invitation to all is to repent and believe, and to trust the Spirit to give life."],
    ],
    discuss: [
      ["Why do you think Nicodemus, a religious leader, struggled to understand new birth?", "He trusted heritage and religion. Discuss how religious people can miss grace."],
      ["What does the picture of wind teach us about the Spirit's work?", "It is invisible, powerful, sovereign and noticeable in effect. We cannot control it."],
      ["What evidence of new birth can we look for in ourselves and others?", "Love for Christ, repentance, desire for God's word, love for believers and growth. See 1 John."],
      ["How should the doctrine of new birth shape the way we share the gospel?", "We call people to repent and believe and trust the Spirit to give life. We do not rely on pressure."],
    ],
    apply: "Examine whether you have truly been born again by the Spirit, looking for the marks of love for Christ, repentance and obedience. If you are unsure, talk to your pastor or teacher this week. Pray for family and friends to be born from above.",
    activity: "Place two seeds, one alive and one dead, on the table. Ask learners what the difference is and whether the dead seed can bring itself to life. Read Ephesians 2:1-5 and John 3:5-8 and discuss how the picture applies to spiritual life.",
    takeHome: "Read John 3:1-21, Ephesians 2:1-10, Titus 3:3-8 and 1 Peter 1:3-5. Write a paragraph on what new birth is and why it matters. Thank God for giving life.",
    prayer: "Thank God for new life in Christ. Pray for those who are spiritually dead. Ask the Spirit to give new birth to our families and friends.",
    teacher: "The meaning of 'born of water' is debated; some see baptism, others see cleansing by the Word and Spirit, others natural birth. Present the main views gently and focus on the necessity of the Spirit's work. Be sensitive to learners who are unsure of their own salvation, and be ready to offer private pastoral conversation.",
    assess: "Weekly check: ask learners why new birth is necessary and who brings it about.",
    mcq1: ["What did Jesus say to Nicodemus about the kingdom of God?", ["Unless one is born again he cannot see it", "He must keep the law perfectly", "He must be a priest", "He must be baptised by John"], 0, "Jesus said unless one is born again he cannot see the kingdom."],
    mcq2: ["To what did Jesus compare the Spirit in John 3:8?", ["The wind", "A river", "A fire", "A mountain"], 0, "He compared the Spirit to the wind."],
    tf: ["People can give themselves spiritual new birth by effort.", false, "New birth is the Spirit's work, a gift of God's mercy."],
    sa: ["What is new birth and why is it necessary?", ["spirit", "born", "dead", "life", "kingdom", "mercy"], "A good answer says new birth is the Spirit giving spiritual life to those dead in sin, and it is necessary to see and enter the kingdom of God."],
  },
  {
    w: 11, title: "Indwelling and Sealing: The Spirit in Every Believer", theme: "The Holy Spirit lives in each believer, making them God's temple and marking them as his own",
    summary: "At conversion, the Holy Spirit takes up residence in the believer. This lesson studies 1 Corinthians 6, Ephesians 1 and Romans 8 to see what indwelling and sealing mean, the guarantee they give and the responsibility they bring.",
    scripture: ["1 Corinthians 6:19-20", "Ephesians 1:13-14"], more: ["Romans 8:9-11", "2 Corinthians 1:21-22", "John 14:17"], memory: "Ephesians 1:13-14",
    objectives: ["Explain what it means that the Spirit indwells believers", "Describe the sealing and the guarantee of the Spirit", "Honour God with our bodies and lives as his temple"],
    terms: [["Indwelling", "The Spirit living within every believer."], ["Seal", "A mark of ownership and security."], ["Guarantee", "A down payment that assures the rest will follow."]],
    intro: "Under the old covenant, God's presence dwelt in the tabernacle and temple. Now, under the new covenant, God's Spirit lives in each believer. Paul asks the Corinthians, 'Do you not know that your body is a temple of the Holy Spirit within you, whom you have from God? You are not your own, for you were bought with a price. So glorify God in your body.' This is a staggering truth with practical implications.",
    context: "Corinth was a city known for immorality. Some believers there thought that what they did with their bodies did not matter. Paul answered that their bodies are members of Christ and temples of the Holy Spirit, so sexual immorality is a sin against one's own body and against God. In Ephesians 1, Paul tells believers that when they heard the word of truth and believed in Christ, they were sealed with the promised Holy Spirit, who is the guarantee of our inheritance until we acquire possession of it.",
    observe: "In Romans 8:9 Paul says, 'You, however, are not in the flesh but in the Spirit, if in fact the Spirit of God dwells in you. Anyone who does not have the Spirit of Christ does not belong to him.' So every believer has the Spirit. The word 'seal' refers to a stamp showing ownership and protection. The word 'guarantee' was used for a down payment or deposit, a first instalment that promises the rest. The Spirit is both the seal and the down payment.",
    points: [
      ["Every believer has the Spirit", "Romans 8:9 is clear: if someone does not have the Spirit of Christ, he does not belong to him. The Spirit does not come to some and not to others at conversion. He enters all who trust Christ. This means we do not need to earn or beg for his presence, though we can ask for more of his fullness."],
      ["The Spirit seals and guarantees our salvation", "A seal marks something as belonging to God and protects it. A guarantee assures that what God has begun he will finish. The Spirit's presence in us is a first instalment of the glory to come. This gives assurance. We can know that we belong to God and that the final inheritance is secure."],
      ["Our bodies are the temple of the Spirit", "Because the Spirit lives within us, we are to honour God in how we use our bodies, our time and our relationships. We belong to God, having been bought with a price. This guards us against immorality, drunkenness and other forms of defilement. It also gives dignity to the body and to ordinary life, which is lived in the presence of God."],
    ],
    discuss: [
      ["How does knowing that the Spirit lives in you change how you view your body and daily life?", "Dignity, responsibility, purity. Discuss practical implications."],
      ["What does it mean that the Spirit is a seal and guarantee?", "Ownership, protection and promise of future inheritance. Discuss assurance."],
      ["Why would Paul make this appeal to the Corinthians about immorality?", "Because they were treating the body as unimportant. Discuss modern parallels."],
      ["How should the church treat a person who has not yet received the Spirit?", "Share the gospel, pray and welcome them. The Spirit comes through faith in Christ."],
    ],
    apply: "Consider one habit or place that is inconsistent with being the temple of the Holy Spirit and decide to change it. Thank God daily for the gift of his presence. Encourage a believer who doubts their salvation by pointing to the sealing of the Spirit.",
    activity: "Show a sealed letter or an official stamp and ask what it means. Discuss how a seal protects and shows ownership. Read Ephesians 1:13-14 and 2 Corinthians 1:21-22 and ask how these ideas apply to the Spirit. Ask learners to write a short thanksgiving for being sealed.",
    takeHome: "Read 1 Corinthians 6:12-20, Ephesians 1:3-14, Romans 8:9-17 and 2 Corinthians 5:5. Write what the Spirit's presence gives believers. Make one commitment to honour God with your body.",
    prayer: "Thank God that his Spirit lives in us. Pray for purity, assurance and gratitude. Ask for help to honour God in all we do.",
    teacher: "Learners who have struggled with sexual sin or addiction may feel shame. Teach with great grace and offer private pastoral support. Make clear that the Spirit's indwelling is a gift and a source of power, not only a standard. Avoid implying that believers who struggle do not have the Spirit.",
    assess: "Weekly check: ask learners what it means that the Spirit seals and indwells believers.",
    mcq1: ["What does 1 Corinthians 6:19 say your body is?", ["A temple of the Holy Spirit", "A prison", "A burden", "A tool"], 0, "Paul says your body is a temple of the Holy Spirit."],
    mcq2: ["What is the Holy Spirit called in Ephesians 1:14?", ["The guarantee of our inheritance", "The judge of our sins", "A gift for a few", "An angel"], 0, "He is the guarantee of our inheritance."],
    tf: ["Romans 8:9 teaches that anyone who does not have the Spirit of Christ does not belong to him.", true, "Paul says so directly."],
    sa: ["What are the implications of the Holy Spirit living in believers?", ["temple", "seal", "guarantee", "body", "honour", "belong"], "A good answer says believers belong to God, are sealed and guaranteed an inheritance, and should honour God with their bodies as his temple."],
  },
  {
    w: 12, title: "Adopted and Assured: Children of God", theme: "The Spirit makes us God's children and testifies with our spirit that we belong to him",
    summary: "One of the Spirit's sweetest works is to assure believers of their adoption. This lesson studies Romans 8 and Galatians 4 to see how the Spirit enables us to cry 'Abba, Father', gives assurance and leads us in obedience.",
    scripture: ["Romans 8:14-17", "Galatians 4:4-7"], more: ["1 John 3:1-3", "1 John 4:13", "Ephesians 1:5"], memory: "Romans 8:15",
    objectives: ["Explain adoption as the work of the Spirit", "Describe how the Spirit gives assurance of salvation", "Live as beloved children, free from fear"],
    terms: [["Adoption", "God making believers his children and heirs."], ["Abba", "An Aramaic word for father, expressing intimate trust."], ["Assurance", "Confidence that we belong to God and will be saved."]],
    intro: "Some believers live in fear that God is distant or that they might not really be his. The Bible offers a better way. Paul says that you did not receive the spirit of slavery to fall back into fear, but you have received the Spirit of adoption as sons, by whom we cry, 'Abba! Father!' The Spirit himself bears witness with our spirit that we are children of God. This lesson explores how the Spirit makes God's fatherhood real to us.",
    context: "In Roman society adoption conferred full legal rights and inheritance, even on slaves. Paul uses this to describe our new status in Christ. In Galatians 4, he says that when the fullness of time had come, God sent forth his Son, born of woman, born under the law, to redeem those who were under the law, so that we might receive adoption as sons. Because you are sons, God has sent the Spirit of his Son into our hearts, crying 'Abba! Father!'",
    observe: "Romans 8:14 says 'For all who are led by the Spirit of God are sons of God.' Verse 16: 'The Spirit himself bears witness with our spirit that we are children of God, and if children, then heirs—heirs of God and fellow heirs with Christ, provided we suffer with him in order that we may also be glorified with him.' The word 'Abba' reflects the intimacy Jesus used when praying to the Father. 1 John 4:13 says 'By this we know that we abide in him and he in us, because he has given us of his Spirit.'",
    points: [
      ["The Spirit makes us God's children", "We are not merely servants or subjects but sons and daughters, adopted at the cost of the Son's life. We have the same Father as Jesus and the right to call him Abba. Adoption means a new family, a new name and a new inheritance. It is a privilege far beyond anything we deserve."],
      ["The Spirit gives inner assurance", "The Spirit bears witness with our spirit that we belong to God. He does this through his word, through the change he works in us and through an inner sense of belonging. This assurance is not presumption but a gift. Alongside it, we examine the evidence of faith and obedience. Assurance can be weak at times, but the Spirit strengthens it."],
      ["Children of God share Christ's sufferings and glory", "Paul says we are heirs with Christ, provided we suffer with him in order that we may also be glorified with him. Sonship does not exempt us from hardship but gives hope in it. Being led by the Spirit means following where he leads, which may include trials. The future inheritance makes present suffering bearable."],
    ],
    discuss: [
      ["What does it mean to you to call God 'Abba, Father'?", "Intimacy, trust, security. Be sensitive to learners with painful experiences of fathers."],
      ["How does the Spirit give us assurance that we are God's children?", "Through Scripture, changed desires, answered prayer and inner witness. Discuss how to test assurance."],
      ["Why might a believer struggle with doubt, and what can help?", "Sin, suffering, false teaching or temperament. Prayer, Scripture, fellowship and counsel can help."],
      ["What does it mean to be a fellow heir with Christ?", "We share his inheritance and, for now, his path of suffering. Discuss hope."],
    ],
    apply: "Start your prayers this week by saying 'Abba, Father' and thanking him for adopting you. Write down three evidences of the Spirit's work in your life as signs of your adoption. Encourage someone who doubts that they belong to God.",
    activity: "Share stories of adoption, perhaps from the class, and talk about what it means for a child to be chosen and given a new name and inheritance. Then read Galatians 4:4-7 and Romans 8:14-17. Ask learners to write a thank-you letter to their heavenly Father.",
    takeHome: "Read Romans 8:12-17, Galatians 4:1-7, Ephesians 1:3-6 and 1 John 3:1-3. List what it means to be an adopted child of God. Memorise Romans 8:15.",
    prayer: "Thank God for adopting us. Cry 'Abba, Father' together. Ask the Spirit to deepen our assurance and our love for the Father.",
    teacher: "Some learners have painful experiences of fathers or of orphan life. Handle this lesson with warmth and let them speak if they wish. Reassure them of God's perfect fatherhood. Also be careful about the balance of assurance and self-examination; avoid both complacency and constant doubt.",
    assess: "Weekly check: ask learners what adoption means and how the Spirit assures us.",
    mcq1: ["What does the Spirit enable believers to cry in Romans 8:15?", ["Abba! Father!", "Lord, have mercy", "Holy, holy, holy", "Hosanna"], 0, "By the Spirit we cry Abba, Father."],
    mcq2: ["What does Romans 8:16 say the Spirit bears witness to?", ["That we are children of God", "That we are strong", "That we are rich", "That we are wise"], 0, "The Spirit bears witness that we are God's children."],
    tf: ["Believers are only servants of God and cannot call him Father.", false, "The Spirit of adoption enables us to call God Abba, Father."],
    sa: ["How does the Spirit assure believers that they are children of God?", ["witness", "abba", "adopted", "spirit", "heirs", "scripture"], "A good answer says the Spirit bears witness with our spirit, enabling us to call God Father, and confirms it through changed lives and Scripture."],
  },
  {
    w: 13, title: "Review and Test: Who the Spirit Is and What He Does in Salvation", theme: "Reviewing the deity and personhood of the Spirit, his work in Scripture, Christ and the believer from the first twelve lessons",
    summary: "This session reviews lessons 1 to 12: who the Spirit is, his personhood and deity, his work in the Old Testament and in Jesus, the promise and Pentecost, inspiration, conviction, new birth, indwelling and adoption. It prepares learners for the mid-session test.",
    scripture: ["John 14:16-17", "Romans 8:14-16"], more: ["Acts 2:1-4", "2 Timothy 3:16", "John 3:5-6"], memory: "Romans 8:14",
    minutes: 60,
    objectives: ["Recall the main teaching about the Holy Spirit from weeks 1 to 12", "Link each truth to a passage of Scripture", "Prepare for the mid-session test with confidence and thanksgiving"],
    terms: [["Holy Spirit", "The third person of the Trinity."], ["Regeneration", "The Spirit's work of giving new spiritual life."], ["Adoption", "God making believers his children and heirs."]],
    intro: "We have spent twelve weeks learning who the Holy Spirit is and what he does in salvation. We have seen that he is a person, fully God, active from creation, anointing Jesus, poured out at Pentecost, inspiring Scripture, convicting the world, giving new birth, indwelling and sealing believers and assuring us that we are God's children. Today we gather those threads and prepare for the test.",
    context: "This is the midpoint of the programme and the default week of the mid-session test, which covers lessons 1 to 12. Churches may hold the test during class time or on another day; where it is on another day, this session serves as a guided review. John 14:16-17 and Romans 8:14-16 sum up the first half: the Helper is with us and in us, and he leads us as children of God.",
    observe: "The first half of the course has focused on the Spirit's person and his work in bringing us to God. The second half will explore his work in the believer's growth, power and gifts, and his role in the life of the church. As we review, notice how the Spirit always points to Christ and glorifies the Father.",
    points: [
      ["The Spirit is a person and is God", "We reviewed John 14 to 16, Acts 5, 2 Corinthians 3 and Matthew 28. He teaches, speaks, guides and can be grieved, which shows that he is a person and not a force. He is eternal, all-knowing and present everywhere. Recall John 14:16-17, Acts 5:3-4 and Psalm 139:7."],
      ["The Spirit has been at work throughout redemption history", "He hovered over creation, empowered leaders and prophets, anointed Jesus, was promised by Joel and Jesus, and poured out at Pentecost. He inspired the Scriptures and illumines readers. Recall Genesis 1:2, Luke 4:18, Joel 2:28, Acts 2:4 and 2 Timothy 3:16."],
      ["The Spirit brings us to God and assures us", "He convicts of sin, gives new birth, indwells and seals believers, and adopts us as children of God. Recall John 16:8, John 3:5-6, Ephesians 1:13-14 and Romans 8:15-16. These are gifts of grace. The second half of the course will show how to live in the Spirit."],
    ],
    discuss: [
      ["Which lesson has most changed how you think about the Holy Spirit?", "Let learners share. Use answers to review. Ask them to support answers from the passage."],
      ["How would you explain to a friend who the Holy Spirit is?", "A person, fully God, who convicts, gives new birth and lives in believers. Let learners give simple explanations."],
      ["How have you experienced the Spirit's work in your own life?", "Conviction, assurance, understanding Scripture. Encourage specific and personal answers."],
      ["What questions do you still have?", "Record them for later sessions and encourage practical questions from learners' own contexts."],
    ],
    apply: "Write a one-page summary of the first twelve lessons with a Scripture reference for each key idea. Review it twice before the test and teach one idea to someone at home. Thank the Spirit in prayer for his work in your life.",
    activity: "Play a team review game: the teacher reads a clue (for example 'hovered over the waters') and teams call out the topic and a passage. Give extra points for application. End by reading Romans 8:14-17 together.",
    takeHome: "Prepare for the test by reviewing the revision map and memory verses. Write five practice questions of your own, with answers, and test someone.",
    prayer: "Thank God for the Holy Spirit. Ask for calm minds for the test. Pray that what we have learned will deepen our walk with the Spirit.",
    teacher: "Explain how the mid-session test works: time, number of questions, and when results are released. Reassure anxious learners. If the test is held on another date, use this session as a review. Close with prayer and encouragement.",
    assess: "This unit is the mid-session test week. The mid-session test covers Lessons 1 to 12 and is built from the approved question bank following the curriculum blueprint.",
    mcq1: ["Which passage tells us the Spirit helps us cry Abba, Father?", ["Romans 8:15", "Genesis 1:1", "Psalm 23", "Matthew 5:3"], 0, "Romans 8:15 speaks of the Spirit of adoption."],
    mcq2: ["What did Jesus promise in John 14:16?", ["Another Helper to be with us forever", "A kingdom on earth", "Great wealth", "An easy life"], 0, "He promised another Helper."],
    tf: ["The mid-session test covers lessons 1 to 12 of this course.", true, "It reviews the first half of the course."],
    sa: ["Summarise in two or three sentences who the Holy Spirit is and what he does in bringing people to God.", ["spirit", "person", "god", "convict", "born", "adopt"], "A good answer says the Spirit is a divine person who convicts of sin, gives new birth, indwells believers and assures them they are children of God."],
  },
];
